type Node struct {
    mu       sync.Mutex
    x, world float64
    dirty    bool
}
func (n *Node) Move(dx float64) { n.mu.Lock(); n.x += dx; n.dirty = true; n.mu.Unlock() }
func (n *Node) World() float64 {
    n.mu.Lock(); defer n.mu.Unlock()
    if n.dirty { n.world = worldOf(n.x); n.dirty = false }   // recompute once
    return n.world
}

