type Node struct {
    mu    sync.Mutex
    x     float64
    dirty atomic.Bool
    world atomic.Pointer[World]
}
func (n *Node) World() World {
    if !n.dirty.Load() { return *n.world.Load() }   // lock-free fast path
    n.mu.Lock(); defer n.mu.Unlock()
    if n.dirty.Load() { n.world.Store(buildWorld(n.x)); n.dirty.Store(false) }
    return *n.world.Load()
}
